DEFINE ROR64(qword, n) {
	count := n % 64
	dest := (qword >> count) | (qword << (64 - count))
	RETURN dest
}
DEFINE SHR64(qword, n) {
	RETURN qword >> n
}
DEFINE s0(qword) {
	RETURN ROR64(qword,1) ^ ROR64(qword, 8) ^ SHR64(qword, 7)
}
